<?php
require_once __DIR__.'/http.php';
function mc_correios_track(string $code): array { $user=(string)getenv('CORREIOS_IDCORREIOS');$pass=(string)getenv('CORREIOS_API_CODE');if(!$user||!$pass)throw new RuntimeException('Credenciais dos Correios não configuradas.');$r=mc_http_json('https://api.correios.com.br/token/v1/autentica','POST',['Authorization'=>'Basic '.base64_encode($user.':'.$pass),'Accept'=>'application/json'],null);if($r['status']<200||$r['status']>=300)throw new RuntimeException('Não foi possível autenticar nos Correios.');$token=$r['data']['token']??'';if(!$token)throw new RuntimeException('Token dos Correios ausente.');$t=mc_http_json('https://api.correios.com.br/srorastro/v1/objetos/'.rawurlencode($code).'?resultado=T','GET',['Authorization'=>'Bearer '.$token,'Accept'=>'application/json']);if($t['status']<200||$t['status']>=300)throw new RuntimeException('Rastreamento dos Correios indisponível.');return $t['data']; }
